import gzip

def load(fn):
 d=[]
 for raw in gzip.open(fn,'rt'):
  if raw.startswith('chrom1'): continue
  p=raw.rstrip().split('\\t')
  if p[0]"'!='"'chr12' or p[3]"'!='"'chr12': continue
  s1,e1,s2,e2=map(int,p[1:5])
  if s1>s2: s1,e1,s2,e2=s2,e2,s1,e1
  d.append((s1,e1,s2,e2,p))
 return d
H1=load('H1_dots.bedpe.gz'); HFF=load('HFF_dots.bedpe.gz')
A,B=7629950,7809597
for name,D in [('H1',H1),('HFF',HFF)]:
 print('\\n',name,'both anchors inside subcomp')
 for s1,e1,s2,e2,p in D:
  if A<=s1 and e1<=B and A<=s2 and e2<=B:
   print(s1,e1,s2,e2,'count',p[9],'donut',p[12],'q',p[16], 'cstart1',p[6],'cstart2',p[7])
print('\\nH1 unique vs HFF exact/overlap in region')
def overlap_key(x,step=5000): return (x[0]//step,x[1]//step,x[2]//step,x[3]//step)
Hset={overlap_key(x) for x in H1}; Fset={overlap_key(x) for x in HFF}
for x in H1:
 if A<=x[0] and x[1]<=B and A<=x[2] and x[3]<=B and overlap_key(x) not in Fset:
  print('H1only inside',x)
for x in HFF:
 if A<=x[0] and x[1]<=B and A<=x[2] and x[3]<=B and overlap_key(x) not in Hset:
  print('HFFonly inside',x)
PY"

